package com.andye.warmod.radar.network;import com.andye.warmod.antiair.AntiAirMissileVariant;import com.andye.warmod.radar.*;import com.andye.warmod.warhead.WarheadPayloadType;import java.util.*;import net.minecraft.network.RegistryFriendlyByteBuf;import net.minecraft.world.phys.Vec3;
public final class RadarNetworkCodecs{static final int MAX_TRACKS=2304,MAX_IMPACTS=128,MAX_TILES=128;private RadarNetworkCodecs(){}public static void writeVec(RegistryFriendlyByteBuf b,Vec3 v){b.writeDouble(v.x);b.writeDouble(v.y);b.writeDouble(v.z);}public static Vec3 readVec(RegistryFriendlyByteBuf b){Vec3 v=new Vec3(b.readDouble(),b.readDouble(),b.readDouble());if(!v.isFinite()||Math.abs(v.x)>3e7||Math.abs(v.z)>3e7||Math.abs(v.y)>32768)throw new IllegalArgumentException("Invalid radar coordinate");return v;}
public static void writeTrack(RegistryFriendlyByteBuf b,RadarTrackSnapshot s){b.writeUUID(s.trackId());b.writeVarInt(s.kind().ordinal());b.writeUUID(s.ownerPlayerId());b.writeUtf(s.ownerDisplayName(),64);b.writeBoolean(s.strategicPayloadType().isPresent());s.strategicPayloadType().ifPresent(p->b.writeVarInt(p.ordinal()));b.writeBoolean(s.interceptorVariant().isPresent());s.interceptorVariant().ifPresent(v->b.writeVarInt(v.ordinal()));b.writeVarInt(s.phase().ordinal());b.writeBoolean(s.carrierPlan().isPresent());s.carrierPlan().ifPresent(p->writeCarrier(b,p));b.writeBoolean(s.terminalPlan().isPresent());s.terminalPlan().ifPresent(p->writeTerminal(b,p));b.writeBoolean(s.interceptorPlan().isPresent());s.interceptorPlan().ifPresent(p->writeInterceptor(b,p));}
public static RadarTrackSnapshot readTrack(RegistryFriendlyByteBuf b){UUID id=b.readUUID();RadarTrackKind kind=enumAt(RadarTrackKind.values(),b.readVarInt());UUID owner=b.readUUID();String name=b.readUtf(64);Optional<WarheadPayloadType> payload=b.readBoolean()?Optional.of(enumAt(WarheadPayloadType.values(),b.readVarInt())):Optional.empty();Optional<AntiAirMissileVariant> variant=b.readBoolean()?Optional.of(enumAt(AntiAirMissileVariant.values(),b.readVarInt())):Optional.empty();RadarTrackPhase phase=enumAt(RadarTrackPhase.values(),b.readVarInt());Optional<RadarCarrierPlanSnapshot> carrier=b.readBoolean()?Optional.of(readCarrier(b)):Optional.empty();Optional<RadarTerminalPlanSnapshot> terminal=b.readBoolean()?Optional.of(readTerminal(b)):Optional.empty();Optional<RadarInterceptorPlanSnapshot> interceptor=b.readBoolean()?Optional.of(readInterceptor(b)):Optional.empty();return new RadarTrackSnapshot(id,kind,owner,name,payload,variant,phase,carrier,terminal,interceptor);}
private static void writeCarrier(RegistryFriendlyByteBuf b,RadarCarrierPlanSnapshot p){writeVec(b,p.launchPosition());writeVec(b,p.burnoutPosition());writeVec(b,p.separationPosition());writeVec(b,p.intendedTarget());b.writeLong(p.launchGameTime());b.writeVarInt(p.ignitionTicks());b.writeVarInt(p.boostTicks());b.writeVarInt(p.coastTicks());b.writeLong(p.visualSeed());}private static RadarCarrierPlanSnapshot readCarrier(RegistryFriendlyByteBuf b){Vec3 a=readVec(b),c=readVec(b),d=readVec(b),e=readVec(b);long t=b.readLong();int i=duration(b,20),boost=duration(b,200),coast=duration(b,1000);long seed=b.readLong();return new RadarCarrierPlanSnapshot(a,c,d,e,t,i,boost,coast,seed);}private static void writeTerminal(RegistryFriendlyByteBuf b,RadarTerminalPlanSnapshot p){b.writeUUID(p.warheadId());writeVec(b,p.startPosition());writeVec(b,p.targetPosition());b.writeLong(p.launchGameTime());b.writeVarInt(p.flightTicks());b.writeLong(p.visualSeed());}private static RadarTerminalPlanSnapshot readTerminal(RegistryFriendlyByteBuf b){return new RadarTerminalPlanSnapshot(b.readUUID(),readVec(b),readVec(b),b.readLong(),duration(b,1000),b.readLong());}
private static void writeInterceptor(RegistryFriendlyByteBuf b,RadarInterceptorPlanSnapshot p){b.writeVarInt(p.variant().ordinal());b.writeBoolean(p.targetRootTrackId().isPresent());p.targetRootTrackId().ifPresent(b::writeUUID);writeVec(b,p.launchPosition());writeVec(b,p.burnoutPosition());b.writeLong(p.launchGameTime());b.writeVarInt(p.ignitionTicks());b.writeVarInt(p.boostTicks());b.writeVarInt(p.guidanceTier());b.writeDouble(p.maximumMissDistance());b.writeBoolean(p.route().isPresent());p.route().ifPresent(r->{writeVec(b,r.controlPoint1());writeVec(b,r.controlPoint2());writeVec(b,r.resolvedInterceptPosition());b.writeVarInt(r.interceptTicks());b.writeLong(r.routeLockGameTime());b.writeDouble(r.resolvedMissDistance());});}private static RadarInterceptorPlanSnapshot readInterceptor(RegistryFriendlyByteBuf b){AntiAirMissileVariant v=enumAt(AntiAirMissileVariant.values(),b.readVarInt());Optional<UUID> target=b.readBoolean()?Optional.of(b.readUUID()):Optional.empty();Vec3 a=readVec(b),c=readVec(b);long time=b.readLong();int ignition=duration(b,20),boost=duration(b,200),tier=b.readVarInt();double max=b.readDouble();Optional<RadarInterceptorRouteSnapshot> route=b.readBoolean()?Optional.of(new RadarInterceptorRouteSnapshot(readVec(b),readVec(b),readVec(b),duration(b,600),b.readLong(),b.readDouble())):Optional.empty();return new RadarInterceptorPlanSnapshot(v,target,a,c,time,ignition,boost,tier,max,route);}
static void writeImpact(RegistryFriendlyByteBuf b,RadarImpactSnapshot s){b.writeUUID(s.rootTrackId());b.writeUUID(s.terminalWarheadId());writeVec(b,s.impactPosition());b.writeLong(s.impactGameTime());b.writeVarInt(s.payloadType().ordinal());b.writeFloat(s.impactVisualScale());}static RadarImpactSnapshot readImpact(RegistryFriendlyByteBuf b){return new RadarImpactSnapshot(b.readUUID(),b.readUUID(),readVec(b),b.readLong(),enumAt(WarheadPayloadType.values(),b.readVarInt()),b.readFloat());}public static void writeTracks(RegistryFriendlyByteBuf b,List<RadarTrackSnapshot> l){b.writeVarInt(Math.min(MAX_TRACKS,l.size()));for(int i=0;i<Math.min(MAX_TRACKS,l.size());i++)writeTrack(b,l.get(i));}static List<RadarTrackSnapshot> readTracks(RegistryFriendlyByteBuf b){int n=count(b,MAX_TRACKS);List<RadarTrackSnapshot> r=new ArrayList<>(n);for(int i=0;i<n;i++)r.add(readTrack(b));return List.copyOf(r);}static void writeImpacts(RegistryFriendlyByteBuf b,List<RadarImpactSnapshot> l){b.writeVarInt(Math.min(MAX_IMPACTS,l.size()));for(int i=0;i<Math.min(MAX_IMPACTS,l.size());i++)writeImpact(b,l.get(i));}static List<RadarImpactSnapshot> readImpacts(RegistryFriendlyByteBuf b){int n=count(b,MAX_IMPACTS);List<RadarImpactSnapshot> r=new ArrayList<>(n);for(int i=0;i<n;i++)r.add(readImpact(b));return List.copyOf(r);}static int count(RegistryFriendlyByteBuf b,int max){int n=b.readVarInt();if(n<0||n>max)throw new IllegalArgumentException("Radar list bound");return n;}private static int duration(RegistryFriendlyByteBuf b,int max){int n=b.readVarInt();if(n<=0||n>max)throw new IllegalArgumentException("Invalid radar duration");return n;}private static<T>T enumAt(T[] v,int i){if(i<0||i>=v.length)throw new IllegalArgumentException("Invalid radar enum");return v[i];}}